# Generated by Copilot AI, edited by me

import os
import csv
import tkinter as tk
from tkinter import filedialog, messagebox
from PIL import Image, ImageTk

class ImageEvaluator:
    def __init__(self, master):
        self.master = master
        self.master.title("Image Evaluator")

        # self.csv_filename = "image_evaluation.csv"
        # self.results = self.load_results()

        # Ask the user to select a directory for images
        self.image_directory = filedialog.askdirectory(title="Select Image Directory")
        if not self.image_directory:
            messagebox.showinfo("No Directory", "No directory selected. Exiting.")
            self.master.destroy()
            return
        
        # Making sure the csv is put with the original files opened
        self.csv_filename = str(self.image_directory) + "/image_evaluation.csv"
        self.results = self.load_results()

        self.valid_extensions = ('.png', '.jpg', '.jpeg', '.gif', '.bmp', '.tiff')

        # Gather images and filter out those already evaluated.
        all_files = os.listdir(self.image_directory)
        self.images = sorted([f for f in all_files if f.lower().endswith(self.valid_extensions)
                              and f not in self.results])

        if not self.images:
            messagebox.showinfo("Processed", "All images have already been evaluated!")
            self.master.destroy()
            return

        self.current_index = 0

        # Create a label to display images.
        self.image_label = tk.Label(self.master)
        self.image_label.pack(padx=10, pady=10)

        # Create a frame for our buttons.
        button_frame = tk.Frame(self.master)
        button_frame.pack(pady=5)

        self.damaged_button = tk.Button(button_frame, text="Damaged",
                                        command=lambda: self.record_answer("damaged"))
        self.damaged_button.pack(side=tk.LEFT, padx=5)
        
        self.not_damaged_button = tk.Button(button_frame, text="Not Damaged",
                                            command=lambda: self.record_answer("not_damaged"))
        self.not_damaged_button.pack(side=tk.LEFT, padx=5)

        self.skip_button = tk.Button(button_frame, text="Skip", command=self.skip_image)
        self.skip_button.pack(side=tk.LEFT, padx=5)
        
        self.quit_button = tk.Button(button_frame, text="Quit", command=self.quit_app)
        self.quit_button.pack(side=tk.LEFT, padx=5)

        self.display_image()

    def load_results(self):
        """Load any already evaluated image results from the CSV file into a dictionary."""
        results = {}
        if os.path.exists(self.csv_filename):
            with open(self.csv_filename, 'r', newline='') as csv_file:
                reader = csv.reader(csv_file)
                for row in reader:
                    if len(row) >= 2:
                        results[row[0]] = row[1]
        return results

    def save_results(self):
        """Save all results back to the CSV file."""
        with open(self.csv_filename, 'w', newline='') as csv_file:
            writer = csv.writer(csv_file)
            for filename, status in self.results.items():
                writer.writerow([filename, status])
    
    def display_image(self):
        """Display the current image in the Tkinter window; if finished, notify and exit."""
        if self.current_index >= len(self.images):
            messagebox.showinfo("Done", "All images have been processed!")
            self.master.destroy()
            return

        image_file = self.images[self.current_index]
        image_path = os.path.join(self.image_directory, image_file)
        try:
            img = Image.open(image_path)
            # Optionally resize the image for display (max 800x600)
            max_size = (800, 600)
            # img.thumbnail(max_size, Image.ANTIALIAS)
            # Making compatible with older versions of PIL
            try:
                resample = Image.Resampling.LANCZOS
            except AttributeError:
                resample = Image.ANTIALIAS

            img.thumbnail(max_size, resample)

            self.photo = ImageTk.PhotoImage(img)
            self.image_label.config(image=self.photo)
            self.master.title(f"Image Evaluator - {image_file}")
        except Exception as error:
            messagebox.showerror("Error", f"Error opening image {image_file}:\n{error}")
            self.current_index += 1
            self.display_image()

    def record_answer(self, answer):
        """Record the answer for the current image and load the next image."""
        image_file = self.images[self.current_index]
        self.results[image_file] = answer
        self.save_results()
        self.current_index += 1
        self.display_image()

    def skip_image(self):
        """Skip the current image and display the next one."""
        # Simply increment the current image index and redisplay.
        self.current_index += 1
        self.display_image()

    def quit_app(self):
        """Save progress and exit the application."""
        self.save_results()
        self.master.destroy()


if __name__ == '__main__':
    root = tk.Tk()
    app = ImageEvaluator(root)
    root.mainloop()
